import he from 'he';
import { humanizePointDueDate } from '../util.js';
import AbstractStatefulView from '../framework/view/abstract-stateful-view.js';
import flatpickr from 'flatpickr';
import 'flatpickr/dist/flatpickr.css';

function createNewEditFormTemplate(point, currentTypeOffers, allDestinations, currentDestination, isDisabled,isSaving,isDeleting) {
  const { type, basePrice, dateFrom, dateTo, offers: selectedOfferIds = [] } = point;
  const { name, description, pictures } = currentDestination || {};
  const dateStart = humanizePointDueDate(dateFrom);
  const dateEnd = humanizePointDueDate(dateTo);

  const getIconByType = (iconType) => {
    const icons = {
      'taxi': 'img/icons/taxi.png',
      'bus': 'img/icons/bus.png',
      'train': 'img/icons/train.png',
      'flight': 'img/icons/flight.png',
      'check-in': 'img/icons/check-in.png',
      'sightseeing': 'img/icons/sightseeing.png',
      'ship': 'img/icons/ship.png',
      'drive': 'img/icons/drive.png',
      'restaurant': 'img/icons/restaurant.png'
    };
    return icons[iconType] || 'img/icons/transport.png';
  };

  const generateOffers = () => {
    if (!currentTypeOffers?.offers?.length) {
      return '';
    }
    return currentTypeOffers.offers.map((offer) => {
      const isChecked = selectedOfferIds.includes(offer.id);
      const safeTitle = he.encode(offer.title);
      const safePrice = he.encode(String(offer.price));
      return `
        <div class="event__offer-selector">
          <input class="event__offer-checkbox visually-hidden"
                 id="event-offer-${offer.id}-1"
                 type="checkbox"
                 name="event-offer-${offer.id}"
                 data-offer-id="${offer.id}"
                 ${isChecked ? 'checked' : ''}
                 ${isDisabled ? 'disabled' : ''}>
          <label class="event__offer-label" for="event-offer-${offer.id}-1">
            <span class="event__offer-title">${safeTitle}</span>
            &plus;&euro;&nbsp;
            <span class="event__offer-price">${safePrice}</span>
          </label>
        </div>
      `;
    }).join('');
  };

  const generateDestinationsList = () =>
    allDestinations.map((dest) => `<option value="${he.encode(dest.name)}"></option>`).join('');

  const generateEventTypes = () => {
    const eventTypes = [
      'taxi', 'bus', 'train', 'flight', 'check-in',
      'sightseeing', 'ship', 'drive', 'restaurant'
    ];
    return eventTypes.map((eventType) => `
      <div class="event__type-item">
        <input id="event-type-${eventType}-1"
               class="event__type-input visually-hidden"
               type="radio"
               name="event-type"
               value="${eventType}"
               ${eventType === type ? 'checked' : ''}
               ${isDisabled ? 'disabled' : ''}>
        <label class="event__type-label event__type-label--${eventType}"
               for="event-type-${eventType}-1">
          ${eventType}
        </label>
      </div>
    `).join('');
  };

  const generatePhotos = () => {
    if (!pictures || !pictures.length) {
      return '';
    }
    return `
      <div class="event__photos-container">
        <div class="event__photos-tape">
          ${pictures.map((pic) => {
    const safeSrc = he.encode(pic.src);
    const safeAlt = pic.description ? he.encode(pic.description) : 'Event photo';
    return `<img class="event__photo" src="${safeSrc}" alt="${safeAlt}">`;
  }).join('')}
        </div>
      </div>
    `;
  };

  const safeName = he.encode(name || '');
  const safeDescription = description ? he.encode(description) : '';
  const safeBasePrice = he.encode(String(basePrice));

  return `
    <form class="event event--edit" action="#" method="post">
      <header class="event__header">
        <div class="event__type-wrapper">
          <label class="event__type event__type-btn" for="event-type-toggle-1">
            <span class="visually-hidden">Choose event type</span>
            <img class="event__type-icon" width="17" height="17"
                 src="${getIconByType(type)}" alt="Event type icon">
          </label>
          <input class="event__type-toggle visually-hidden" id="event-type-toggle-1" type="checkbox">
          <div class="event__type-list">
            <fieldset class="event__type-group">
              <legend class="visually-hidden">Event type</legend>
              ${generateEventTypes()}
            </fieldset>
          </div>
        </div>

        <div class="event__field-group event__field-group--destination">
          <label class="event__label event__type-output" for="event-destination-1">${he.encode(type)}</label>
          <input class="event__input event__input--destination" id="event-destination-1"
                 type="text" name="event-destination" value="${safeName}"
                 list="destination-list-1" placeholder="Select destination">
          <datalist id="destination-list-1">${generateDestinationsList()}</datalist>
        </div>

        <div class="event__field-group event__field-group--time">
          <label class="visually-hidden" for="event-start-time-1">From</label>
          <input class="event__input event__input--time" id="event-start-time-1"
                 type="text" name="event-start-time" value="${he.encode(dateStart)}">
          &mdash;
          <label class="visually-hidden" for="event-end-time-1">To</label>
          <input class="event__input event__input--time" id="event-end-time-1"
                 type="text" name="event-end-time" value="${he.encode(dateEnd)}">
        </div>

        <div class="event__field-group event__field-group--price">
          <label class="event__label" for="event-price-1"><span class="visually-hidden">Price</span>&euro;</label>
          <input class="event__input event__input--price" id="event-price-1"
                 type="number" name="event-price" value="${safeBasePrice}" min="0">
        </div>

        <button class="event__save-btn btn btn--blue" type="submit" ${isDisabled ? 'disabled' : ''}>${isSaving ? 'saving...' : 'save'}</button>
        <button class="event__reset-btn" type="reset" ${isDisabled ? 'disabled' : ''} >${isDeleting ? 'deleting...' : 'delete'}</button>
        <button class="event__rollup-btn" type="button">
          <span class="visually-hidden">Open event</span>
        </button>
      </header>

      <section class="event__details">
        ${currentTypeOffers?.offers?.length ? `
          <section class="event__section event__section--offers">
            <h3 class="event__section-title event__section-title--offers">Offers</h3>
            <div class="event__available-offers">${generateOffers()}</div>
          </section>
        ` : ''}

        ${description || pictures ? `
          <section class="event__section event__section--destination">
            <h3 class="event__section-title event__section-title--destination">Destination</h3>
            <p class="event__destination-description">${safeDescription}</p>
            ${generatePhotos()}
          </section>
        ` : ''}
      </section>
    </form>
  `;
}

export default class NewEditFormView extends AbstractStatefulView {
  #allOffers = null;
  #allDestinations = null;
  #handleFormSubmit = null;
  #handleEditRollUp = null;
  #handleDeleteClick = null;
  #datepickerStart = null;
  #datepickerEnd = null;

  constructor({ point, typeOffers, allOffers, allDestinations, onFormSubmit, onEditRollup, onDeleteClick }) {
    super();
    this._setState(NewEditFormView.parsePointToState(point, typeOffers));
    this.#allOffers = allOffers;
    this.#allDestinations = allDestinations;
    this.#handleFormSubmit = onFormSubmit;
    this.#handleEditRollUp = onEditRollup;
    this.#handleDeleteClick = onDeleteClick;
    this._restoreHandlers();
  }

  get template() {
    const currentDestination = this.#allDestinations.find(
      (dest) => dest.id === this._state.destination
    ) || { name: '', description: '', pictures: [] };
    return createNewEditFormTemplate(
      this._state,
      this._state.typeOffers,
      this.#allDestinations,
      currentDestination,
      this._state.isDisabled,
      this._state.isSaving,
      this._state.isDeleting,
    );
  }

  reset(point) {
    const typeOffers = this.#allOffers.find((item) => item.type === point.type);
    const newState = NewEditFormView.parsePointToState(point, typeOffers);
    this.updateElement(newState);
  }

  _restoreHandlers() {
    this.element.addEventListener('submit', this.#formSubmitHandler);
    this.element.querySelector('.event__rollup-btn')
      ?.addEventListener('click', this.#editRollUpHandler);
    this.element.querySelector('.event__reset-btn')
      ?.addEventListener('click', this.#deleteClickHandler);
    this.element.querySelector('.event__type-group')
      ?.addEventListener('change', this.#typeListChangeHandler);
    this.element.querySelector('.event__input--destination')
      ?.addEventListener('input', this.#destinationChangeHandler);
    this.element.querySelector('.event__input--price')
      ?.addEventListener('input', this.#priceChangeHandler);
    this.element.querySelector('.event__available-offers')
      ?.addEventListener('change', this.#offersChangeHandler);
    this.#setDatepickerStart();
    this.#setDatepickerEnd();
  }

  #formSubmitHandler = (evt) => {
    evt.preventDefault();
    const { dateFrom, dateTo } = this._state;
    if (!dateFrom || !dateTo){
      this.shake();
      return;
    }
    if (new Date(dateFrom) > new Date(dateTo)){
      this.shake();
      return;
    }
    this.#handleFormSubmit(NewEditFormView.parseStateToPoint(this._state));
  };

  #deleteClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleDeleteClick?.(NewEditFormView.parseStateToPoint(this._state));
  };

  #dateFromChangeHandler = ([userDate]) => {
    this._setState({ dateFrom: userDate });
    this.#updateDatepickersConstraints();
  };

  #dateToChangeHandler = ([userDate]) => {
    this._setState({ dateTo: userDate });
    this.#updateDatepickersConstraints();
  };

  #updateDatepickersConstraints() {
    if (this.#datepickerStart) {
      const maxDate = this._state.dateTo ? new Date(this._state.dateTo) : null;
      this.#datepickerStart.set('maxDate', maxDate);
    }
    if (this.#datepickerEnd) {
      const minDate = this._state.dateFrom ? new Date(this._state.dateFrom) : null;
      this.#datepickerEnd.set('minDate', minDate);
    }
  }

  #setDatepickerStart() {
    const defaultDate = this._state.dateFrom ? new Date(this._state.dateFrom) : undefined;
    this.#datepickerStart = flatpickr(
      this.element.querySelector('#event-start-time-1'),
      {
        dateFormat: 'd/m/y H:i',
        enableTime: true,
        'time_24hr': true,
        defaultDate: defaultDate,
        onChange: this.#dateFromChangeHandler,
        maxDate: this._state.dateTo ? new Date(this._state.dateTo) : null,
      }
    );
    if (!this._state.dateFrom) {
      this.#datepickerStart.clear();
    }
  }

  #setDatepickerEnd() {
    const defaultDate = this._state.dateTo ? new Date(this._state.dateTo) : undefined;
    this.#datepickerEnd = flatpickr(
      this.element.querySelector('#event-end-time-1'),
      {
        dateFormat: 'd/m/y H:i',
        enableTime: true,
        'time_24hr': true,
        defaultDate: defaultDate,
        onChange: this.#dateToChangeHandler,
        minDate: this._state.dateFrom ? new Date(this._state.dateFrom) : null,
      }
    );
    if (!this._state.dateTo) {
      this.#datepickerEnd.clear();
    }
  }

  shake() {
    this.element.style.animation = 'shake 0.5s ease-in-out';
    setTimeout(() => {
      this.element.style.animation = '';
    }, 500);
  }

  #editRollUpHandler = (evt) => {
    evt.preventDefault();
    this.#handleEditRollUp(NewEditFormView.parseStateToPoint(this._state));
  };

  #typeListChangeHandler = (evt) => {
    evt.preventDefault();
    const targetType = evt.target.value;
    const typeOffers = this.#allOffers.find((item) => item.type === targetType);
    this.updateElement({
      type: targetType,
      typeOffers: typeOffers,
      offers: []
    });
  };

  #destinationChangeHandler = (evt) => {
    const targetName = evt.target.value;
    const newDestination = this.#allDestinations.find((item) => item.name === targetName);
    if (newDestination) {
      this.updateElement({ destination: newDestination.id });
    }
  };

  #priceChangeHandler = (evt) => {
    evt.preventDefault();
    const value = parseInt(evt.target.value, 10);
    this.updateElement({ basePrice: isNaN(value) ? 0 : value });
  };

  #offersChangeHandler = (evt) => {
    if (!evt.target.classList.contains('event__offer-checkbox')){
      return;
    }
    const offerId = evt.target.dataset.offerId;
    let updatedOffers = [...this._state.offers];
    if (evt.target.checked) {
      if (!updatedOffers.includes(offerId)){
        updatedOffers.push(offerId);
      }
    } else {
      updatedOffers = updatedOffers.filter((id) => id !== offerId);
    }
    this.updateElement({ offers: updatedOffers });
  };

  static parsePointToState(point, typeOffers) {
    return {
      ...point,
      typeOffers: typeOffers,
      offers: point.offers || [],
      isDisabled: false,
      isSaving: false,
      isDeleting: false,
    };
  }

  static parseStateToPoint(state) {
    const point = { ...state };
    delete point.typeOffers;
    delete point.isDisabled;
    delete point.isSaving;
    delete point.isDeleting;
    return point;
  }
}
